  gold_X[0][18]=128'hf931f914f8f7f8daf8bdf8a0f883f866;
  gold_X[0][19]=128'hfa19f9fcf9dff9c2f9a5f988f96bf94e;
  gold_X[0][20]=128'hfb01fae4fac7faaafa8dfa70fa53fa36;
  gold_X[0][21]=128'hfbe9fbccfbaffb92fb75fb58fb3bfb1e;
  gold_X[0][22]=128'hfcd1fcb4fc97fc7afc5dfc40fc23fc06;
  gold_X[0][23]=128'hfdb9fd9cfd7ffd62fd45fd28fd0bfcee;
  gold_X[0][24]=128'hfea1fe84fe67fe4afe2dfe10fdf3fdd6;
  gold_X[0][25]=128'hff89ff6cff4fff32ff15fef8fedbfebe;
  gold_X[0][26]=128'h007100540037001afffdffe0ffc3ffa6;
  gold_X[0][27]=128'h0159013c011f010200e500c800ab008e;
  gold_X[0][28]=128'h02410224020701ea01cd01b001930176;
  gold_X[0][29]=128'h0329030c02ef02d202b50298027b025e;
  gold_X[0][30]=128'h041103f403d703ba039d038003630346;
  gold_X[0][31]=128'h04f904dc04bf04a204850468044b042e;
  gold_X[0][32]=128'h05e105c405a7058a056d055005330516;
  gold_X[0][33]=128'h06c906ac068f067206550638061b05fe;
  gold_X[0][34]=128'h07b107940777075a073d0720070306e6;
  gold_X[0][35]=128'hf89cf87ff862f845f828f80b07eb07ce;
  gold_X[0][36]=128'hf984f967f94af92df910f8f3f8d6f8b9;
  gold_X[0][37]=128'hfa6cfa4ffa32fa15f9f8f9dbf9bef9a1;
  gold_X[0][38]=128'hfb54fb37fb1afafdfae0fac3faa6fa89;
  gold_X[0][39]=128'hfc3cfc1ffc02fbe5fbc8fbabfb8efb71;
  gold_X[0][40]=128'hfd24fd07fceafccdfcb0fc93fc76fc59;
